def raw(name):
 row=payload[name];data=base64.b64decode(row['base64'],validate=True);assert len(data)==row['bytes'] and hashlib.sha256(data).hexdigest()==row['sha256'];return data
def new(path,data):
 with path.open('xb') as f:f.write(data);f.flush();os.fsync(f.fileno())
