go=m.strict_json(m.verify_ref(expected['go']).decode());assert go['issued_at_ns']==field['recorded_at_ns'] and go['expires_at_ns']==field['recorded_at_ns']+600_000_000_000
m.validate_go(go,plan,time.time_ns());c.tool_identity(m,config['diagnostic_tool'])
temporary=phase/'config.readonly12.final.r12.tmp';new(temporary,raw('config.readonly12.r12.json'));assert config_path.read_bytes()==old_raw;os.replace(temporary,config_path)
assert reference(config_path)==expected['config']
argv=['/home/loosqk/.local/share/uv/python/cpython-3.12.13-linux-aarch64-gnu/bin/python3',expected['candidate']['path'],'--config',str(config_path)]
started=time.time_ns();child=subprocess.Popen(argv,stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE);stdout,stderr=child.communicate();code=child.wait()
new(phase/'final-config-plan.r12.stdout',stdout);new(phase/'final-config-plan.r12.stderr',stderr)
receipt={'argv':argv,'pid':child.pid,'started_ns':started,'finished_ns':time.time_ns(),'exit_code':code,'wait_returncode':code,'reaped':True,'signals_sent':[],'stdout':reference(phase/'final-config-plan.r12.stdout'),'stderr':reference(phase/'final-config-plan.r12.stderr')}
new(phase/'final-config-plan.r12.receipt.json',(json.dumps(receipt,ensure_ascii=False,indent=2)+'\n').encode())
